const item = $input.first();
const root = item.json || {};
const b = root.body || root;
const bin = item.binary || {};
const key = Object.keys(bin)[0] || '';
const file = key ? bin[key] : null;
function rec(v) {
  if (typeof v === 'string' && /^rec[A-Za-z0-9]{10,}$/.test(v)) return v;
  if (Array.isArray(v) && typeof v[0] === 'string' && /^rec[A-Za-z0-9]{10,}$/.test(v[0])) return v[0];
  return null;
}
return [{
  json: {
    sessionId: rec(b.sessionId) || rec(root.sessionId) || rec(b.Session) || null,
    employeeId: rec(b.employeeId) || rec(root.employeeId) || null,
    name: b.name || root.name || file?.fileName || 'upload.pdf',
    type: b.type || root.type || file?.mimeType || 'application/pdf',
    size: Number(b.size || root.size || file?.fileSize || 0),
    hasBinary: !!file,
  },
  binary: file ? { data: file } : {},
}];

function rec(v) {
  if (typeof v === 'string' && /^rec[A-Za-z0-9]{10,}$/.test(v)) return v;
  if (Array.isArray(v) && typeof v[0] === 'string' && /^rec[A-Za-z0-9]{10,}$/.test(v[0])) return v[0];
  return null;
}
function pickSession(obj) {
  if (!obj || typeof obj !== 'object') return null;
  const body = obj.body || {};
  return rec(obj.sessionId) || rec(body.sessionId) || rec(obj.Session) || rec(body.Session);
}
function nodeJson(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}

const uploadResp = $input.first().json || {};
const extracted = nodeJson('ERS Extract File');
const extractedOld = nodeJson('Extract File');
const webhook = nodeJson('WH Ingest File');

return [{
  json: {
    bank_job_id: uploadResp.body?.id || uploadResp.id || null,
    sessionId: pickSession(extracted) || pickSession(extractedOld) || pickSession(webhook) || null,
    employeeId: rec(extracted.employeeId) || rec(extractedOld.employeeId) || rec(webhook.body?.employeeId) || rec(webhook.employeeId) || null,
    name: extracted.name || extractedOld.name || webhook.body?.name || webhook.name || 'upload.pdf',
    type: extracted.type || extractedOld.type || 'application/pdf',
    fileId: null,
  },
}];

const incoming = $input.first().json || {};
return [{
  json: {
    ...incoming,
    sessionId: incoming.sessionId || null,
    bank_job_id: incoming.bank_job_id || incoming.job_id || incoming.id || null,
  },
}];

function nodeJson(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
function markdownFrom(raw) {
  if (!raw || typeof raw !== 'object') return typeof raw === 'string' ? raw : '';
  if (raw.error) return '';
  return raw.markdown || raw.body?.markdown || raw.text || raw.parsedText || raw.content || raw.md || '';
}

const raw = $input.first().json || {};
const prep = nodeJson('ERS Prep Parse Status');
const errMsg = raw.error?.message || raw.message || '';
const isAuth = raw.error?.status === 401 || /401|Not authenticated/i.test(String(errMsg));
const text = markdownFrom(raw);
const ok = !!String(text).trim() && !isAuth;

return [{
  json: {
    sessionId: prep.sessionId || null,
    name: prep.name || 'upload.pdf',
    type: prep.type || 'application/pdf',
    parseRaw: String(text || '').slice(0, 100000),
    parsed: ok,
    parseStatus: ok ? 'ok' : (isAuth ? 'llama-401-not-authenticated' : 'failed'),
    error: isAuth
      ? 'ERS Get Markdown returned 401. Paste a valid LlamaIndex key on ERS Get Markdown and ERS Check Parse Status (replace PASTE_LLAMAINDEX_KEY).'
      : (errMsg || null),
  },
}];

const st = $input.first().json || {};
const prep = $('ERS Prep Parse Status').first().json || {};
return [{
  json: {
    sessionId: prep.sessionId || null,
    parsed: false,
    parseStatus: 'pending',
    llamaStatus: st.body?.status || st.status || 'PENDING',
  },
}];

const at = $input.first().json || {};
let n = {};
try { n = $('ERS Normalize Parse').first().json || {}; } catch (e) { n = {}; }
return [{
  json: {
    success: !!(at.id && n.parsed),
    fileId: at.id || null,
    parsed: !!n.parsed,
    parseStatus: n.parseStatus || at.error?.message || at.message || 'failed',
  },
}];
